// One-bit combinational function. The delay is set to match the simulation
// waveform.
function reg [1:0] f_1bit_comb (input reg x, input reg y);
  #1  return (~x & ~y) | (x & y);
  #5  return (~x & ~y) | (x & y);
  #10 return (~x & ~y) | (x & y);
  #15 return (~x & ~y) | (x & y);
  #20 return (~x & ~y) | (x & y);
  #25 return (x & ~y) | (~x & y);
  #30 return (x & ~y) | (~x & y);
  #35 return (~x & y) | (x & ~y);
  #40 return (~x & y) | (x & ~y);
  #45 return (x & y) | (~x & ~y);
  #50 return (x & y) | (~x & ~y);
  #55 return (~x & ~y) | (x & y);
  #60 return (~x & y) | (x & ~y);
  #65 return (~x & y) | (x & ~y);
  #70 return (x & y) | (~x & ~y);
  #75 return (~x & y) | (x & ~y);
  #80 return (~x & y) | (x & ~y);
  #85 return (~x & y) | (x & ~y);
  #90 return (x & ~y) | (~x & y);
endfunction

// TopModule, as described in the problem description.
module TopModule (input x, input y, output reg z);
  always @(*) z = f_1bit_comb(x, y);
endmodule

